{
  "case_id": "xsu_sg_007_work_stopped_due_to_impairment",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Konklusionen om, at arbejdsophør ikke i sig selv giver ret, er korrekt. Svaret påstår dog, at SU-handicaptillæg afgøres af SU-myndigheden under Uddannelses- og Forskningsstyrelsen og ikke af Udbetaling Danmark. Det strider mod SU-bekendtgørelsen § 36, stk. 1 og § 37 samt vejledningen, hvor Udbetaling Danmark er myndigheden. Det er en væsentlig juridisk fejl. Svaret nævner desuden ikke selve den centrale vurdering af arbejdets karakter."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret nævner ikke, at arbejdets karakter sammenholdes med funktionsnedsættelsen. Det nævner heller ikke, at man vurderer, om ansøgeren kan varetage andre typer arbejde med skånehensyn eller i mindre omfang. Det omtaler kun generelt 'hvilke opgaver og timetal ansøgeren kunne klare', hvilket kun delvist rammer elementerne."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Svaret besvarer første del (ikke i sig selv ret), men svarer forkert på anden del om, hvad Udbetaling Danmark vurderer. Det afviser Udbetaling Danmark som myndighed i stedet for at beskrive vurderingen efter vejledningen."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som lovbestemmelse, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om kilder understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer, at afgørelsen træffes af SU-myndigheden under Uddannelses- og Forskningsstyrelsen. Det har ingen støtte i materialet og modsiges af det. Formuleringen 'reelt næsten ikke kan have et erhvervsarbejde' er en omskrivning af lovens 'meget betydelige begrænsninger', som ikke er helt præcis."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer, at arbejdsophør ikke i sig selv afgør retten, og at det er en konkret vurdering. Det udelader dog vurderingen af andre typer arbejde med skånehensyn eller mindre omfang. Det nævner heller ikke, at ikke-fysisk belastende arbejde kun er et eksempel."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svarets egne trin hænger sammen: arbejdsophør er ikke tilstrækkeligt, arbejdsevnen er afgørende, og dokumentation indgår i en samlet vurdering. Konklusionen følger af disse trin. Fejlen om myndigheden er et indholdsproblem, ikke en intern modsigelse."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret gør myndighedsfordelingen næsten absolut ('ikke Udbetaling Danmark'), selvom 'normalt' er brugt, og det er forkert i forhold til kilderne. Ellers er formuleringerne som 'kan indgå' og 'ikke i sig selv' passende."
    }
  },
  "xhaile_coverage": {
    "A22": {
      "label": "partial",
      "reason": "Svaret behandler, at arbejdet er ophørt på grund af funktionsnedsættelsen, som udgangspunkt for en samlet vurdering. Det angiver ikke, at arbejdets karakter vurderes i forhold til funktionsnedsættelsen, og det henfører vurderingen til en forkert myndighed."
    },
    "A23": {
      "label": "partial",
      "reason": "Svaret nævner kun indirekte, at timetal og opgaver ansøgeren kunne klare indgår. Det siger ikke eksplicit, at myndigheden vurderer andre typer arbejde med skånehensyn eller i mindre omfang, og det udpeger forkert myndighed."
    }
  },
  "overall_notes": "Svaret har korrekt hovedpointe (arbejdsophør giver ikke automatisk ret), men udelader de kritiske elementer om arbejdets karakter og andre typer arbejde med skånehensyn. Det indeholder en væsentlig fejl om, at SU-myndigheden og ikke Udbetaling Danmark afgør sagen, og det angiver ingen kilder."
}

